 "stage_label": "Predict and explain image formation using converging/diverging behaviour and reflection laws",
 "synthesis": true,
 "roles": [
  {
   "actor": "Students (Individual)",
   "role_description": "Each student independently constructs the master synthesis table from memory and notes, then uses it to answer the two novel-scenario prediction questions in writing."
  },
  {
   "actor": "Teacher",
   "role_description": "Introduces the synthesis table structure, confirms the column headings without pre-filling any cells, and poses the two novel-scenario questions after table completion."
